(330, 7, 'reading', 'What is the email about?', '["A delayed shipment", "A new hire", "A price increase", "A holiday"]', 0, 'Email báo lô hàng đến trễ 3 ngày do tắc cảng.', 'comprehension', 'logistics', 610, 'Dear Ms. Hoang,\n\nWe regret to inform you that your shipment (Order #7712) will arrive three days late due to port congestion. It is now expected on Friday. We apologize for the inconvenience and offer free storage for one month.\n\nSincerely,\nLogiFast Support'),
(331, 7, 'reading', 'When is the shipment expected?', '["On Friday", "On Monday", "Tomorrow", "Next month"]', 0, '"...expected on Friday".', 'comprehension', 'logistics', 610, 'Dear Ms. Hoang,\n\nWe regret to inform you that your shipment (Order #7712) will arrive three days late due to port congestion. It is now expected on Friday. We apologize for the inconvenience and offer free storage for one month.\n\nSincerely,\nLogiFast Support'),
(332, 7, 'reading', 'What does the company offer?', '["Free storage for one month", "A full refund", "A discount", "Express delivery"]', 0, '"...offer free storage for one month".', 'comprehension', 'logistics', 610, 'Dear Ms. Hoang,\n\nWe regret to inform you that your shipment (Order #7712) will arrive three days late due to port congestion. It is now expected on Friday. We apologize for the inconvenience and offer free storage for one month.\n\nSincerely,\nLogiFast Support'),
(333, 7, 'reading', 'What did the survey find?', '["Most staff want flexible hours", "Most staff want higher pay", "Most staff dislike the canteen", "Most staff want new computers"]', 0, '78% nhân viên muốn giờ làm linh hoạt.', 'comprehension', 'hr', 611, 'STAFF SURVEY RESULTS\n\nOut of 200 employees, 78% said flexible working hours matter most to them. Only 12% ranked salary as the top priority. The HR team will pilot a four-day week in the sales department starting next quarter.'),
(334, 7, 'reading', 'What will HR pilot?', '["A four-day week in sales", "A pay raise", "A new canteen", "Remote work for all"]', 0, '"...pilot a four-day week in the sales department...".', 'comprehension', 'hr', 611, 'STAFF SURVEY RESULTS\n\nOut of 200 employees, 78% said flexible working hours matter most to them. Only 12% ranked salary as the top priority. The HR team will pilot a four-day week in the sales department starting next quarter.'),
(335, 7, 'reading', 'How many employees joined the survey?', '["200", "78", "12", "100"]', 0, '"Out of 200 employees...".', 'comprehension', 'hr', 611, 'STAFF SURVEY RESULTS\n\nOut of 200 employees, 78% said flexible working hours matter most to them. Only 12% ranked salary as the top priority. The HR team will pilot a four-day week in the sales department starting next quarter.'),
(336, 7, 'reading', 'What happened at the bank?', '["A system upgrade", "A robbery", "A fire", "A merger"]', 0, 'Ngân hàng nâng cấp hệ thống cuối tuần.', 'comprehension', 'finance', 612, 'Dear customers,\n\nOur online banking system will be upgraded this weekend. From Saturday 10 p.m. to Sunday 6 a.m., transfers and payments will be unavailable. ATMs will work normally. Thank you for your understanding.\n\nCityBank'),
(337, 7, 'reading', 'Which service stays available?', '["ATMs", "Transfers", "Payments", "Balance checks online"]', 0, '"ATMs will work normally".', 'comprehension', 'finance', 612, 'Dear customers,\n\nOur online banking system will be upgraded this weekend. From Saturday 10 p.m. to Sunday 6 a.m., transfers and payments will be unavailable. ATMs will work normally. Thank you for your understanding.\n\nCityBank'),
(338, 7, 'reading', 'When will the upgrade finish?', '["Sunday 6 a.m.", "Saturday 10 p.m.", "Monday morning", "Friday evening"]', 0, '"...to Sunday 6 a.m.".', 'comprehension', 'finance', 612, 'Dear customers,\n\nOur online banking system will be upgraded this weekend. From Saturday 10 p.m. to Sunday 6 a.m., transfers and payments will be unavailable. ATMs will work normally. Thank you for your understanding.\n\nCityBank'),
(339, 7, 'reading', 'What is being announced?', '["A new flight route", "A new airport", "Cheaper tickets", "A new airline"]', 0, 'Mở đường bay thẳng Hà Nội – Seoul.', 'comprehension', 'travel', 613, 'SKYVIET AIRLINES\n\nWe are excited to launch direct flights between Hanoi and Seoul starting July 1st. Flights depart daily at 9:40 p.m. and take about five hours. Early-bird fares start from $99 one way. Book now on our website!'),
(340, 7, 'reading', 'When do the flights start?', '["July 1st", "June 1st", "August 1st", "May 1st"]', 0, '"...starting July 1st".', 'comprehension', 'travel', 613, 'SKYVIET AIRLINES\n\nWe are excited to launch direct flights between Hanoi and Seoul starting July 1st. Flights depart daily at 9:40 p.m. and take about five hours. Early-bird fares start from $99 one way. Book now on our website!'),
